vi.mock("@/lib/rate-limit", async (original) => ({
  ...(await original<typeof import("@/lib/rate-limit")>()),
  consumeBudgets: vi.fn().mockResolvedValue(undefined),
}));
import { beforeEach, describe, expect, it, vi } from "vitest";
const boundary = vi.hoisted(() => ({
  tx: {
    $queryRaw: vi.fn(),
    user: { findUnique: vi.fn(), findUniqueOrThrow: vi.fn() },
    systemControl: { findUnique: vi.fn() },
    contact: { findMany: vi.fn(), createMany: vi.fn() },
  },
  user: vi.fn(),
  parse: vi.fn(),
  validate: vi.fn(),
}));
vi.mock("@/lib/db", () => ({
  db: { $transaction: (work: (tx: unknown) => unknown) => work(boundary.tx) },
}));
vi.mock("@/lib/session", () => ({
  requireUser: boundary.user,
}));
vi.mock("next/cache", () => ({ revalidatePath: vi.fn() }));
vi.mock("@/lib/inngest", () => ({ dispatchPending: vi.fn() }));
vi.mock("@/lib/imports", () => ({
  parseContacts: boundary.parse,
  validateImportRows: boundary.validate,
}));
import { importContacts } from "@/lib/actions";

const freeUser = {
  id: "owner",
  plan: "FREE",
  subscriptionStatus: "NONE",
  currentPeriodStart: null,
  currentPeriodEnd: null,
  dodoSubscriptionId: null,
  gracePeriodEnd: null,
  planOverride: null,
  planOverrideStartsAt: null,
  planOverrideExpiresAt: null,
  grandfatheredUntil: null,
  isSuspended: false,
  deletionRequestedAt: null,
  gmailAuthorized: true,
};
describe("actual import action checks entitlement before inspecting input", () => {
  beforeEach(() => {
    vi.resetAllMocks();
    boundary.user.mockResolvedValue({
      id: "owner",
      plan: "PAID",
      isAdmin: true,
    });
    boundary.tx.user.findUnique.mockResolvedValue(freeUser);
    boundary.tx.user.findUniqueOrThrow.mockResolvedValue({
      preferredRoles: [],
    });
    boundary.tx.systemControl.findUnique.mockResolvedValue({
      sendingEnabled: true,
      paidGatingEnabled: true,
    });
    boundary.tx.contact.findMany.mockResolvedValue([]);
    boundary.tx.contact.createMany.mockResolvedValue({ count: 1 });
    boundary.parse.mockReturnValue([
      {
        state: "valid",
        name: "Ada",
        email: "[REDACTED_EMAIL]",
        company: "",
        jobRole: "Software Engineer",
      },
    ]);
    boundary.validate.mockImplementation((rows) =>
      rows.map((row: object) => ({ ...row, state: "valid" })),
    );
  });
  it.each([
    "bad",
    "x".repeat(1024 * 1024 + 1),
    [],
    [{ email: "bad" }],
    Array(1001).fill(null),
    null,
    123,
  ])(
    "denies Free input %# without parsing, validation, lookup or insertion",
    async (input) => {
      expect(await importContacts(input)).toMatchObject({
        ok: false,
        code: "UPGRADE_REQUIRED",
      });
      expect(boundary.parse).not.toHaveBeenCalled();
      expect(boundary.validate).not.toHaveBeenCalled();
      expect(boundary.tx.contact.findMany).not.toHaveBeenCalled();
      expect(boundary.tx.contact.createMany).not.toHaveBeenCalled();
    },
  );
  it("does not inspect malicious array elements before denying", async () => {
    const input = [
      {
        get name(): never {
          throw new Error("validation reached input");
        },
      },
    ];
    expect(await importContacts(input)).toMatchObject({
      code: "UPGRADE_REQUIRED",
    });
  });
  it.each(["PAID", "LEGACY"])(
    "permits both import paths for %s",
    async (mode) => {
      if (mode === "PAID")
        boundary.tx.user.findUnique.mockResolvedValue({
          ...freeUser,
          planOverride: "PAID",
          planOverrideStartsAt: new Date(0),
        });
      else
        boundary.tx.systemControl.findUnique.mockResolvedValue({
          sendingEnabled: true,
          paidGatingEnabled: false,
        });
      expect((await importContacts("CSV input")).ok).toBe(true);
      expect(
        (
          await importContacts([
            {
              name: "Ada",
              email: "[REDACTED_EMAIL]",
              jobRole: "Software Engineer",
            },
          ])
        ).ok,
      ).toBe(true);
      expect(boundary.parse).toHaveBeenCalledOnce();
      expect(boundary.validate).toHaveBeenCalledOnce();
      expect(boundary.tx.contact.createMany).toHaveBeenCalledTimes(2);
    },
  );
});
